* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, sans-serif; font-size: 16px; background: #14231f; color: #f3f0df; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 24px 16px; background: radial-gradient(ellipse at 50% 0%, #2d5142 0, #14231f 68%); }
.lot-card { width: min(100%, 680px); padding: clamp(20px, 5vw, 38px); border: 2px solid #527461; border-radius: 18px; background: #20372e; box-shadow: 0 18px 55px #09120f99; }
.header { display: flex; align-items: center; justify-content: space-between; gap: 18px; }
.eyebrow, footer, .lane-label { color: #a9c9a4; font-size: .78rem; font-weight: 800; letter-spacing: .14em; }
.eyebrow { margin: 0 0 8px; }
h1 { margin: 0; font-size: clamp(1.8rem, 6vw, 2.7rem); line-height: 1.05; letter-spacing: -.04em; }
.subtitle { margin: 9px 0 0; color: #c6d4c6; }
.sign { flex: 0 0 66px; height: 66px; display: grid; place-content: center; border: 3px solid #f3f0df; border-radius: 12px; color: #f3f0df; font-size: 2rem; font-weight: 900; line-height: .8; text-align: center; transform: rotate(3deg); }
.sign span { display: block; margin-top: 6px; font-size: .58rem; letter-spacing: .16em; }
.stats { display: grid; grid-template-columns: 1fr 1fr 1.2fr; gap: 10px; margin: 26px 0; }
.stats p { min-height: 72px; display: flex; flex-direction: column; justify-content: center; gap: 2px; margin: 0; padding: 12px 16px; border: 1px solid #527461; border-radius: 10px; background: #172a23; }
.stats strong { color: #e7c96c; font-size: 1.5rem; line-height: 1; }
.stats span { color: #bdd0bd; font-size: .72rem; font-weight: 800; letter-spacing: .1em; }
.stats .capacity { align-items: flex-end; }
.stats .capacity strong { color: #f3f0df; font-size: .95rem; }
.controls { display: grid; grid-template-columns: auto minmax(120px, 1fr); align-items: center; gap: 8px 14px; margin-bottom: 22px; }
.controls label { font-weight: 750; }
input { width: 100%; min-width: 0; min-height: 46px; padding: 10px 13px; border: 2px solid #527461; border-radius: 8px; background: #14231f; color: #f3f0df; font: inherit; }
input::placeholder { color: #9eb2a2; }
input:focus-visible, button:focus-visible { outline: 3px solid #e7c96c; outline-offset: 3px; }
.hint { grid-column: 2; margin: -4px 0 0; color: #adc1b0; font-size: .82rem; }
.lot { padding: 18px; border: 2px dashed #75917a; border-radius: 12px; background: #1a3028; }
.lane-label { margin: 0 0 10px; text-align: center; }
.spaces { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 10px; }
.space { min-width: 0; min-height: 92px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; padding: 7px 3px; border: 2px solid #75917a; border-radius: 8px; background: #294537; color: #f3f0df; cursor: pointer; font: inherit; transition: transform .12s, border-color .12s, background .12s; }
.space:hover { transform: translateY(-2px); border-color: #e7c96c; background: #355641; }
.space:active { transform: translateY(1px) scale(.98); }
.space .number { align-self: flex-start; padding-left: 5px; color: #bdd0bd; font-size: .72rem; font-weight: 800; }
.car { font-size: 1.55rem; line-height: 1; }
.plate { max-width: 100%; overflow: hidden; color: #e7c96c; font-size: .62rem; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }
.space.occupied { border-style: solid; border-color: #d99b67; background: #553f31; }
.space.occupied .number { color: #f1c28e; }
.space.match { outline: 3px solid #e7c96c; outline-offset: 2px; box-shadow: 0 0 18px #e7c96c77; }
.space.match .plate { color: #fff0a8; }
.drive-lane { min-height: 45px; display: flex; align-items: center; justify-content: space-between; margin: 12px 0; padding: 0 12px; border-top: 2px dashed #527461; border-bottom: 2px dashed #527461; color: #a9c9a4; font-size: .72rem; font-weight: 800; letter-spacing: .2em; }
.drive-lane span { color: #e7c96c; font-size: 1.2rem; }
.message { min-height: 24px; margin: 18px 0 14px; color: #e7c96c; text-align: center; }
footer { padding-top: 14px; border-top: 1px solid #527461; text-align: center; }
[hidden] { display: none !important; }
@media (max-width: 480px) { body { padding: 12px; } .lot-card { padding: 20px 16px; } .stats { gap: 6px; } .stats p { min-height: 68px; padding: 10px 8px; } .spaces { gap: 7px; } .space { min-height: 82px; } .lot { padding: 12px 8px; } }

const spacesEl = document.querySelector('#spaces');
const searchEl = document.querySelector('#plate-search');
const searchStatus = document.querySelector('#search-status');
const message = document.querySelector('#message');
const freeCount = document.querySelector('#free-count');
const occupiedCount = document.querySelector('#occupied-count');
const spaces = Array(12).fill(null);

for (let index = 0; index < spaces.length; index += 1) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'space';
  button.dataset.index = index;
  button.setAttribute('aria-label', `Space ${index + 1}, free`);
  button.innerHTML = `<span class="number">${String(index + 1).padStart(2, '0')}</span><span class="car" aria-hidden="true">▱</span><span class="plate">FREE</span>`;
  button.addEventListener('click', () => toggleSpace(index));
  spacesEl.append(button);
}

function render() {
  let occupied = 0;
  const query = searchEl.value.trim().toUpperCase();
  spacesEl.querySelectorAll('.space').forEach((button, index) => {
    const plate = spaces[index];
    const isOccupied = Boolean(plate);
    if (isOccupied) occupied += 1;
    button.classList.toggle('occupied', isOccupied);
    button.classList.toggle('match', Boolean(query && plate && plate.includes(query)));
    button.querySelector('.car').textContent = isOccupied ? '🚗' : '▱';
    button.querySelector('.plate').textContent = plate || 'FREE';
    button.setAttribute('aria-label', `Space ${index + 1}, ${isOccupied ? `occupied by ${plate}; click to remove` : 'free; click to park'}`);
  });
  freeCount.textContent = spaces.length - occupied;
  occupiedCount.textContent = occupied;
  const matches = spaces.filter(plate => plate && query && plate.includes(query)).length;
  searchStatus.textContent = query ? (matches ? `${matches} matching space${matches === 1 ? '' : 's'} highlighted.` : 'No matching plates.') : 'Search highlights a matching space.';
}

function toggleSpace(index) {
  if (spaces[index]) {
    const plate = spaces[index];
    spaces[index] = null;
    message.textContent = `${plate} checked out from space ${index + 1}.`;
    render();
    return;
  }
  const plate = window.prompt(`Enter the license plate for space ${index + 1}:`);
  if (plate === null) return;
  const cleanPlate = plate.trim().toUpperCase();
  if (!cleanPlate) {
    message.textContent = 'Enter a plate to park your car.';
    return;
  }
  spaces[index] = cleanPlate;
  message.textContent = `${cleanPlate} parked in space ${index + 1}.`;
  render();
}

searchEl.addEventListener('input', render);
render();
